head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    textbox1.setValue(anchor1.getAttribute("role"));
};
scwin.tabControl1_onchange = function(tabID, idx, userTabID) {
    textbox2.setValue("tab1 : aria-selected = " +
        tabControl1.getTabHostAndContainer().tabhost.childNodes[0].firstChild.firstChild.getAttribute("aria-selected") +
        "<br/>tab1 : aria-hidden = " +
        tabControl1.getTabHostAndContainer().tabhost.childNodes[0].firstChild.firstChild.getAttribute("aria-hidden")
    );
    textbox3.setValue("tab2 : aria-selected = " +
        tabControl1.getTabHostAndContainer().tabhost.childNodes[1].firstChild.firstChild.getAttribute("aria-selected") +
        "<br/>tab2 : aria-hidden = " +
        tabControl1.getTabHostAndContainer().tabhost.childNodes[1].firstChild.firstChild.getAttribute("aria-hidden")
    );
};
scwin.tabControl2_onchange = function(tabID, idx, userTabID) {
    textbox4.setValue("tab1 : aria-selected = " +
        tabControl2.getTabHostAndContainer().tabhost.childNodes[0].firstChild.firstChild.getAttribute("aria-selected") +
        "<br/>tab1 : aria-hidden = " +
        tabControl2.getTabHostAndContainer().tabhost.childNodes[0].firstChild.firstChild.getAttribute("aria-hidden")
    );
    textbox5.setValue("tab2 : aria-selected = " +
        tabControl2.getTabHostAndContainer().tabhost.childNodes[1].firstChild.getAttribute("aria-selected") +
        "<br/>tab2 : aria-hidden = " +
        tabControl2.getTabHostAndContainer().tabhost.childNodes[1].firstChild.getAttribute("aria-hidden")
    );
};
scwin.checkVal1 = function() {
    var temp = WebSquare.wUnit.getDomById($p.id + 'textbox2').innerText;
    return temp.indexOf('tab1 : aria-selected = false') >= 0;
}
scwin.checkVal2 = function() {
    var temp = WebSquare.wUnit.getDomById($p.id + 'textbox2').innerText;
    return temp.indexOf('tab1 : aria-selected = true') >= 0;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').setActiveTab(0)");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
